<?php declare(strict_types=1);require __DIR__.'/../includes/auth.php';$sent=false;$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&csrf_check($_POST['csrf_token']??'')){$email=strtolower(trim($_POST['email']??''));$s=db()->prepare('SELECT id,full_name,email FROM admin_users WHERE email=? AND is_active=1');$s->execute([$email]);$u=$s->fetch();if($u){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);db()->prepare('DELETE FROM password_reset_tokens WHERE admin_user_id=? OR expires_at<NOW()')->execute([$u['id']]);db()->prepare('INSERT INTO password_reset_tokens(admin_user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 60 MINUTE))')->execute([$u['id'],$hash]);$link=BASE_URL.'/admin/reset_password.php?token='.rawurlencode($token);$html='<p>Hello '.e($u['full_name']).',</p><p>Use the link below within 60 minutes to reset your ZNP Development Admin password.</p><p><a href="'.e($link).'">Reset Password</a></p><p>If you did not request this, you may ignore this email.</p>';app_send_mail($u['email'],'Reset your ZNP Development Admin password',$html);} $sent=true;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="../assets/design-system.css"><title>Forgot Password</title></head><body class="admin-body"><main class="admin-login"><form method="post" class="admin-card admin-login-card"><h1>Reset Password</h1><?php if($sent):?><div class="status success">If an active account exists for that email, a reset link has been sent.</div><?php else:?><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Email</label><input type="email" name="email" required><button class="primary admin-login-button">Send Reset Link</button><?php endif;?><a class="admin-forgot-link" href="login.php">Back to Sign In</a></form></main></body></html>